messages = {message_id: Message(message_id) for message_id in range(11)}
calls = []
def fake_get_chat_messages(message_id):
    calls.append(message_id)
    start = max(0, message_id - 5)
    end = min(10, message_id + 5)
    return [messages[current] for current in range(start, end + 1)]
globals()['get_chat_messages'] = fake_get_chat_messages
assert [message.id for message in merge_windows([2, 4, 6])] == list(range(11))
assert calls == [2, 4, 6]

messages = {message_id: Message(message_id) for message_id in range(8)}
windows = {1: [messages[0], messages[1], messages[2]], 5: [messages[2], messages[5], messages[7]]}
calls = []
def fake_get_chat_messages(message_id):
    calls.append(message_id)
    return windows[message_id]
globals()['get_chat_messages'] = fake_get_chat_messages
assert [message.id for message in merge_windows([1, 1, 5])] == [0, 1, 2, 5, 7]
assert calls == [1, 1, 5]
